mapper.select:
select flow_id, flow_key, flow_name, status, remark, create_by, create_time, update_by, update_time from pm_flow_definition
and flow_key like concat('%', #{flowKey}, '%') and flow_name like concat('%', #{flowName}, '%') and status = #{status}
order by flow_id desc

mapper.update:
update pm_flow_definition
set status = #{status}, update_by = #{updateBy}, update_time = sysdate()
where flow_id = #{flowId}
